(()=>{const links=[...document.querySelectorAll('[data-mobile-nav]')];function active(id){links.forEach(a=>a.classList.toggle('dock-active',a.dataset.mobileNav===id))}links.forEach(a=>a.addEventListener('click',()=>active(a.dataset.mobileNav)));if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio);if(visible[0])active(visible[0].target.id)},{rootMargin:'-80px 0px -45% 0px',threshold:[0,.1,.3]});['home','courses','week'].forEach(id=>{const section=document.getElementById(id);if(section)observer.observe(section)})}if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js').catch(()=>{}));})();
